K = 2
img = Image.new('RGB', (len(ROWS[0]) // K, len(ROWS)))
for y, row in enumerate(ROWS):
    for x in range(img.width):
        img.putpixel((x, y), PALETTE[row[x * K:x * K + K]])
img.resize((img.width * 8, img.height * 8), Image.NEAREST).show()
